import json
import re
from datetime import datetime

def parse_tutar(tutar_str):
    if isinstance(tutar_str, (int, float)):
        return float(tutar_str)

    # Temizleme: ₺, TL ve boşlukları kaldır
    s = str(tutar_str).replace('₺', '').replace('TL', '').strip()
    if not s:
        return None

    # Nokta ve virgül mantığı
    has_comma = ',' in s
    has_dot = '.' in s

    if has_comma and has_dot:
        # Hem , hem . varsa: . binlik, , ondalık (Örn: 1.234,50)
        s = s.replace('.', '').replace(',', '.')
    elif has_comma:
        # Yalnızca , varsa: ondalık ayırıcı
        s = s.replace(',', '.')
    elif has_dot:
        # Yalnızca . varsa: 3 rakam sonrası ise binlik, değilse ondalık
        parts = s.split('.')
        if len(parts) == 2 and len(parts[1]) == 3:
            s = s.replace('.', '') # Binlik ayırıcıyı kaldır
        else:
            pass # Zaten ondalık formatında (örn: 7.5)

    try:
        return float(s)
    except ValueError:
        return None

def parse_tarih(tarih_str):
    formats = [
        "%Y-%m-%d", "%Y/%m/%d", "%d.%m.%Y"
    ]
    # Türkçe ay isimleri için sözlük
    aylar = {
        'Ocak': '01', 'Şubat': '02', 'Mart': '03', 'Nisan': '04', 'Mayıs': '05', 'Haziran': '06',
        'Temmuz': '07', 'Ağustos': '08', 'Eylül': '09', 'Ekim': '10', 'Kasım': '11', 'Aralık': '12'
    }

    # "2 Nisan 2025" formatı için regex ve dönüşüm
    tr_match = re.search(r'(\d{1,2})\s+([a-zA-ZİİçşğüöçŞĞÜÖÇ]+)\s+(\d{4})', tarih_str)
    if tr_match:
        gun = tr_match.group(1).zfill(2)
        ay_adi = tr_match.group(2)
        yil = tr_match.group(3)
        for a, v in aylar.items():
            if ay_adi.lower() == a.lower():
                tarih_str = f"{yil}-{v}-{gun}"
                break
        else:
            return None

    for fmt in formats:
        try:
            dt = datetime.strptime(tarih_str, fmt)
            # Geçerli tarih kontrolü (datetime zaten bunu yapar ama mantıksal kontrol için)
            return dt
        except ValueError:
            continue
    return None

def process():
    valid_records = {} # id -> record
    error_count = 0
    total_lines = 0

    with open('siparisler.jsonl', 'r', encoding='utf-8') as f:
        for line in f:
            total_lines += 1
            stripped = line.strip()
            if not stripped:
                continue

            try:
                data = json.loads(stripped)
                # Alan kontrolü
                required = ['id', 'musteri', 'tutar', 'tarih', 'durum']
                if not all(k in data for k in required):
                    error_count += 1
                    continue

                # Tutar parse
                tutar = parse_tutar(data['tutar'])
                if tutar is None:
                    error_count += 1
                    continue

                # Tarih parse
                tarih_dt = parse_tarih(str(data['tarih']))
                if not tarih_dt:
                    error_count += 1
                    continue

                # Müşteri ve Durum temizliği
                musteri = str(data['musteri']).strip()
                durum = str(data['durum']).strip().lower()
                # Türkçe karakter duyarlılığı (İPTAL -> iptal)
                if durum == 'iptal' or durum == 'i̇ptal': # Unicode i issue prevention
                    durum = 'iptal'

                record = {
                    "id": data['id'],
                    "musteri": musteri,
                    "tutar": tutar,
                    "tarih": tarih_dt.strftime("%Y-%m-%d"),
                    "durum": durum
                }

                # Aynı id varsa son geçerli olanı al
                valid_records[data['id']] = record

            except Exception:
                error_count += 1

    # İstatistikler
    gecerli_kayitlar = list(valid_records.values())
    iptal_sayisi = sum(1 for r in gecerli_kayitlar if r['durum'] == 'iptal')

    iptal_olmayanlar = [r for r in gecerli_kayitlar if r['durum'] != 'iptal']
    toplam_tutar = sum(r['tutar'] for r in iptal_olmayanlar)

    aylik = {}
    en_cok_harcayan_musteri = None
    max_spend = -1.0
    customer_spending = {}

    for r in iptal_olmayanlar:
        # Aylık toplam
        yil_ay = r['tarih'][:7]
        aylik[yil_ay] = aylik.get(yil_ay, 0) + r['tutar']

        # Müşteri harcama
        customer_spending[r['musteri']] = customer_spending.get(r['musteri'], 0) + r['tutar']

    for cust, spend in customer_spending.items():
        if spend > max_spend:
            max_spend = spend
            en_cok_harcayan_musteri = cust

    # Yuvarlama ve Sonuç Hazırlama
    result = {
        "gecerli_kayit": len(valid_records),
        "hatali_satir": error_count,
        "iptal_sayisi": iptal_sayisi,
        "toplam_tutar": round(toplam_tutar, 2),
        "aylik": {k: round(v, 2) for k, v in aylik.items()},
        "en_cok_harcayan": en_cok_harcayan_musteri
    }

    with open('ozet.json', 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    process()

